        <section class="call-detail-card call-detail-wide"><div class="call-detail-section-head"><h2>Conversation Transcript<span>Speaker-separated manual transcript generation</span></h2>@can('call_management_transcribe')@if(!in_array($clientCallLog->transcription_status,['completed','queued','processing'],true) && $clientCallLog->recording_url)<form method="POST" action="{{ route('client-call-history.transcribe',$clientCallLog) }}">@csrf<button class="call-transcribe-btn" type="submit"><i class="material-icons">auto_awesome</i> Generate Transcript</button></form>@elseif(in_array($clientCallLog->transcription_status,['queued','processing'],true))<button class="call-transcribe-btn" disabled>Processing…</button>@endif @endcan</div>
            @if($clientCallLog->transcription_status === 'completed')<div class="transcript-conversation">@forelse($conversation as $line)@php $speaker=(int)$line['speaker']; @endphp<div class="transcript-row {{ $speaker % 2 ? 'alt' : '' }}"><span class="transcript-avatar">S{{ $speaker+1 }}</span><div class="transcript-bubble"><div class="transcript-meta"><span>Speaker {{ $speaker+1 }}</span>@if($line['start'] !== null)<span class="transcript-time">{{ gmdate('i:s',(int)$line['start']) }}</span>@endif</div>{{ $line['text'] }}</div></div>@empty<div class="transcript-empty">{{ $clientCallLog->transcript ?: 'No transcript returned.' }}</div>@endforelse</div>@elseif($clientCallLog->transcription_status === 'failed')<p>Transcription failed. You can retry using Generate Transcript.</p>@else<p>Transcript has not been generated yet.</p>@endif
